import * as v from 'valibot';
import { minimumZoneWarningMs } from './enemyZoneFairness';

const positive = v.pipe(v.number(), v.finite(), v.minValue(Number.MIN_VALUE));
const nonnegative = v.pipe(v.number(), v.finite(), v.minValue(0));
const ms = v.pipe(nonnegative, v.safeInteger());
const count = v.pipe(nonnegative, v.safeInteger());

/** Area hit of a colossus action around a point: players, decoys and allies in full, structures as collateral. */
const ImpactSchema = v.strictObject({
  radiusPx: positive,
  damage: nonnegative,
  /** Damage at the edge of the radius (linear falloff from `damage` in the centre). */
  minDamage: nonnegative,
  /** Push for players only. */
  knockbackSpeed: nonnegative,
  knockbackMs: ms,
  friendlyBaseDamageMult: nonnegative,
  constructionDamageMult: nonnegative,
  trainDamageMult: nonnegative,
});

/** Burning chunks of an action; fire style and targets follow the body's faction. */
const ChunksSchema = v.strictObject({
  count,
  searchRadius: nonnegative,
  flightMs: v.pipe(positive, v.safeInteger()),
  igniteCenter: v.boolean(),
  durationMs: ms,
  burnDurationMs: ms,
  burnDamagePerTick: nonnegative,
  sourceId: v.pipe(v.string(), v.minLength(1)),
});

export const InfernoColossusConfigSchema = v.strictObject({
  phaseTwoHpRatio: v.pipe(positive, v.maxValue(1)),
  /** The freshly spawned body stands this long before it starts walking. */
  spawnHoldMs: ms,
  /** Pause after every big action before the next one may start. */
  actionGapMs: ms,
  /** No big action in the first moments after the boss rose. */
  initialDelayMs: ms,
  phaseTwo: v.strictObject({
    moveSpeedMultiplier: v.pipe(positive, v.minValue(1)),
    /** Rear-up, cracks bursting open and the shockwave; the body stands and stays vulnerable. */
    transitionMs: v.pipe(positive, v.safeInteger()),
    zoneAtMs: ms,
    burstAtMs: v.pipe(positive, v.safeInteger()),
    burst: ImpactSchema,
    fireChunks: ChunksSchema,
  }),
  glutstoss: v.strictObject({
    /** A player, decoy, base surface or construction inside this radius triggers the blast. */
    triggerRadiusPx: positive,
    cooldownMs: ms,
    chargeMs: v.pipe(positive, v.safeInteger()),
    recoverMs: ms,
    burst: ImpactSchema,
    fireChunks: ChunksSchema,
  }),
  incendiary: v.strictObject({
    minRangePx: nonnegative,
    maxRangePx: positive,
    cooldownMs: ms,
    windupMs: v.pipe(positive, v.safeInteger()),
    recoverMs: ms,
    /** Flight time at the minimum and maximum range (linear in between). */
    flightMinMs: v.pipe(positive, v.safeInteger()),
    flightMaxMs: v.pipe(positive, v.safeInteger()),
    /** Shells in phase 2 (phase 1 fires one); the extra ones land beside the main point. */
    phaseTwoCount: v.pipe(count, v.minValue(1), v.maxValue(5)),
    fanSpreadPx: nonnegative,
    /** Muzzle at the abdomen tip, behind the body centre. */
    sourceBackPx: nonnegative,
    impact: ImpactSchema,
    fireChunks: ChunksSchema,
  }),
  siege: v.strictObject({
    cooldownMs: ms,
    /** First siege no earlier than this after phase 2 began. */
    phaseTwoDelayMs: ms,
    durationMs: v.pipe(positive, v.safeInteger()),
    waveAtMs: v.pipe(v.array(ms), v.minLength(1), v.maxLength(6)),
    perWave: v.pipe(count, v.minValue(1), v.maxValue(32)),
    weaponId: v.pipe(v.string(), v.minLength(1)),
    /** Launch ring on the opened elytra. */
    launchRingPx: nonnegative,
    /** Players and structures within this range are assigned; the rest of a wave goes to ground points. */
    rangePx: positive,
    perPlayerCap: v.pipe(count, v.minValue(1)),
    perStructureCap: count,
    /** Turn limit of the homing after `acquireDelayMs`. */
    turnDegPerSec: positive,
    acquireDelayMs: ms,
  }),
  /** Aimed Glutkäfer salvo that the walking body fires alongside its flame; blocks neither movement nor flame. */
  beetleSalvo: v.strictObject({
    cooldownMs: ms,
    /** The body lights up this long before the first beetle leaves. */
    windupMs: v.pipe(positive, v.safeInteger()),
    count: v.pipe(count, v.minValue(1), v.maxValue(12)),
    intervalMs: v.pipe(positive, v.safeInteger()),
    recoverMs: ms,
    weaponId: v.pipe(v.string(), v.minLength(1)),
    /** Launch point ahead of the body centre, along its facing. */
    muzzleForwardPx: nonnegative,
    /** Random aim scatter per beetle, ± degrees. */
    spreadDeg: nonnegative,
    /** Only players and decoys within this range are shot at. */
    rangePx: positive,
    /** Turn limit of the homing after `acquireDelayMs`. */
    turnDegPerSec: positive,
    acquireDelayMs: ms,
  }),
  stormFlight: v.strictObject({
    cooldownMs: ms,
    phaseTwoDelayMs: ms,
    minRangePx: positive,
    maxRangePx: positive,
    takeoffMs: v.pipe(positive, v.safeInteger()),
    speedPxPerSec: positive,
    recoverMs: ms,
    /** Search for free ground for the body around the target point, in cells. */
    landingSearchCells: v.pipe(count, v.maxValue(8)),
    chunkEveryPx: positive,
    trailChunks: ChunksSchema,
    landing: ImpactSchema,
    landingChunks: ChunksSchema,
  }),
});

export type InfernoColossusConfig = v.InferOutput<typeof InfernoColossusConfigSchema>;
export type InfernoColossusImpactConfig = InfernoColossusConfig['glutstoss']['burst'];
export type InfernoColossusChunksConfig = InfernoColossusConfig['glutstoss']['fireChunks'];

/**
 * Parse the authored block and reject relations no schema can express: every red zone must give a
 * player in its centre time to leave it, and the timelines must be ordered.
 */
export function normalizeInfernoColossusConfig(raw: unknown, enemyId: string): InfernoColossusConfig {
  const config = v.parse(InfernoColossusConfigSchema, raw);
  const fail = (what: string): never => { throw new Error(`[coopDefenseEnemies] Inferno colossus ${what}: ${enemyId}`); };
  const { phaseTwo, glutstoss, incendiary, siege, stormFlight } = config;
  if (phaseTwo.zoneAtMs >= phaseTwo.burstAtMs || phaseTwo.burstAtMs > phaseTwo.transitionMs) fail('transition timeline out of order');
  if (phaseTwo.burstAtMs - phaseTwo.zoneAtMs < minimumZoneWarningMs(phaseTwo.burst.radiusPx)) fail('shockwave warning too short');
  if (glutstoss.chargeMs < minimumZoneWarningMs(glutstoss.burst.radiusPx)) fail('Glutstoss warning too short');
  if (incendiary.minRangePx >= incendiary.maxRangePx || incendiary.flightMinMs > incendiary.flightMaxMs) fail('incendiary range invalid');
  if (incendiary.windupMs + incendiary.flightMinMs < minimumZoneWarningMs(incendiary.impact.radiusPx)) fail('incendiary warning too short');
  if (siege.waveAtMs.some((at, index) => at >= siege.durationMs || (index > 0 && at <= siege.waveAtMs[index - 1]))) fail('siege waves out of order');
  if (stormFlight.minRangePx >= stormFlight.maxRangePx) fail('storm flight range invalid');
  const shortestFlightMs = stormFlight.takeoffMs + stormFlight.minRangePx / stormFlight.speedPxPerSec * 1000;
  if (shortestFlightMs < minimumZoneWarningMs(stormFlight.landing.radiusPx)) fail('storm flight warning too short');
  for (const minDamage of [phaseTwo.burst, glutstoss.burst, incendiary.impact, stormFlight.landing]) {
    if (minDamage.minDamage > minDamage.damage) fail('impact minDamage above damage');
  }
  return config;
}
