/**
 * Vertrag der frei belegbaren Spielersteuerung.
 *
 * Diese Datei kennt weder Phaser noch i18n: Sie definiert die Aktionen, ihre Standardbelegung,
 * welche Eingaben ueberhaupt belegbar sind, und die Regeln fuer Tausch und Kollision. Die
 * Laufzeit-Wahrheit haelt `controlBindingStore`, gespeichert wird ueber `localPreferences`.
 *
 * Gespeichert werden ausschliesslich Abweichungen vom Standard. Aendert sich spaeter ein
 * Standard, erreicht er damit jeden Spieler, der diese Aktion nie umgestellt hat.
 */

export type ControlActionId =
  | 'moveUp'
  | 'moveLeft'
  | 'moveDown'
  | 'moveRight'
  | 'dash'
  | 'interact'
  | 'utility'
  | 'utilityWheel'
  | 'ultimate'
  | 'arenaPanel';

export type ControlActionGroup = 'movement' | 'actions' | 'interface';

/** `MouseEvent.button`: 1 = mittlere Taste, 3 = Zurueck (Maustaste 4), 4 = Vor (Maustaste 5). */
export type ControlMouseButton = 1 | 3 | 4;

export type ControlBinding =
  | { readonly device: 'key'; readonly code: number; readonly label?: string }
  | { readonly device: 'mouse'; readonly button: ControlMouseButton };

export interface ControlActionDefinition {
  readonly id: ControlActionId;
  readonly group: ControlActionGroup;
  /** i18n-Key der Aktionsbezeichnung im Belegungsdialog. */
  readonly labelKey: string;
  readonly defaultBinding: ControlBinding;
}

/** Explizites `null` = vom Spieler (durch einen Tausch) unbelegt gelassen. */
export type ControlBindingOverrides = Partial<Record<ControlActionId, ControlBinding | null>>;
export type ResolvedControlBindings = Readonly<Record<ControlActionId, ControlBinding | null>>;

/** Die von der Steuerung benutzten `KeyboardEvent.keyCode`-Werte (identisch mit Phasers KeyCodes). */
export const KEY_CODES = {
  BACKSPACE: 8,
  TAB: 9,
  ENTER: 13,
  SHIFT: 16,
  CTRL: 17,
  ALT: 18,
  ESC: 27,
  SPACE: 32,
  PAGE_UP: 33,
  PAGE_DOWN: 34,
  END: 35,
  HOME: 36,
  LEFT: 37,
  UP: 38,
  RIGHT: 39,
  DOWN: 40,
  PRINT_SCREEN: 44,
  A: 65,
  B: 66,
  D: 68,
  E: 69,
  K: 75,
  L: 76,
  M: 77,
  N: 78,
  P: 80,
  Q: 81,
  R: 82,
  S: 83,
  T: 84,
  W: 87,
  META_LEFT: 91,
  META_RIGHT: 92,
  CONTEXT_MENU: 93,
  F1: 112,
  F8: 119,
  F10: 121,
  F11: 122,
  F12: 123,
  SLASH: 191,
  QUOTE: 222,
  IME_PROCESS: 229,
} as const;

const key = (code: number): ControlBinding => ({ device: 'key', code });

export const CONTROL_ACTIONS: readonly ControlActionDefinition[] = [
  { id: 'moveUp', group: 'movement', labelKey: 'ui.controls.action.moveUp', defaultBinding: key(KEY_CODES.W) },
  { id: 'moveLeft', group: 'movement', labelKey: 'ui.controls.action.moveLeft', defaultBinding: key(KEY_CODES.A) },
  { id: 'moveDown', group: 'movement', labelKey: 'ui.controls.action.moveDown', defaultBinding: key(KEY_CODES.S) },
  { id: 'moveRight', group: 'movement', labelKey: 'ui.controls.action.moveRight', defaultBinding: key(KEY_CODES.D) },
  { id: 'dash', group: 'movement', labelKey: 'ui.controls.action.dash', defaultBinding: key(KEY_CODES.SPACE) },
  { id: 'interact', group: 'actions', labelKey: 'ui.controls.action.interact', defaultBinding: key(KEY_CODES.SHIFT) },
  { id: 'utility', group: 'actions', labelKey: 'ui.controls.action.utility', defaultBinding: key(KEY_CODES.E) },
  { id: 'utilityWheel', group: 'actions', labelKey: 'ui.controls.action.utilityWheel', defaultBinding: key(KEY_CODES.R) },
  { id: 'ultimate', group: 'actions', labelKey: 'ui.controls.action.ultimate', defaultBinding: key(KEY_CODES.Q) },
  { id: 'arenaPanel', group: 'interface', labelKey: 'ui.controls.action.arenaPanel', defaultBinding: key(KEY_CODES.TAB) },
];

export const CONTROL_ACTION_IDS: readonly ControlActionId[] = CONTROL_ACTIONS.map((action) => action.id);

const ACTION_BY_ID = new Map(CONTROL_ACTIONS.map((action) => [action.id, action] as const));

export function isControlActionId(value: unknown): value is ControlActionId {
  return typeof value === 'string' && ACTION_BY_ID.has(value as ControlActionId);
}

export function getControlActionDefinition(id: ControlActionId): ControlActionDefinition {
  return ACTION_BY_ID.get(id)!;
}

/**
 * Nie belegbar: Esc ist der feste Menue-/Zurueck-Stapel, F11/F12 gehoeren Browser bzw.
 * Vollbild und Entwicklerwerkzeugen, OS- und Drucktasten erreichen das Spiel nicht verlaesslich.
 */
const RESERVED_KEY_CODES: ReadonlySet<number> = new Set([
  KEY_CODES.ESC,
  KEY_CODES.F11,
  KEY_CODES.F12,
  KEY_CODES.META_LEFT,
  KEY_CODES.META_RIGHT,
  KEY_CODES.CONTEXT_MENU,
  KEY_CODES.PRINT_SCREEN,
  KEY_CODES.IME_PROCESS,
]);

const MOUSE_BUTTONS: ReadonlySet<number> = new Set([1, 3, 4]);

/** Tasten mit eigener Browser-Standardaktion (Scrollen, Fokuswechsel, Schnellsuche, Menueleiste ...). */
const BROWSER_CAPTURE_KEY_CODES: ReadonlySet<number> = new Set([
  KEY_CODES.BACKSPACE,
  KEY_CODES.TAB,
  KEY_CODES.ALT,
  KEY_CODES.SPACE,
  KEY_CODES.PAGE_UP,
  KEY_CODES.PAGE_DOWN,
  KEY_CODES.END,
  KEY_CODES.HOME,
  KEY_CODES.LEFT,
  KEY_CODES.UP,
  KEY_CODES.RIGHT,
  KEY_CODES.DOWN,
  KEY_CODES.SLASH,
  KEY_CODES.QUOTE,
  ...Array.from({ length: KEY_CODES.F10 - KEY_CODES.F1 + 1 }, (_, index) => KEY_CODES.F1 + index),
]);

const MAX_KEY_LABEL_LENGTH = 4;

export function isReservedKeyCode(code: number): boolean {
  return RESERVED_KEY_CODES.has(code);
}

/** Buchstaben bleiben ohne Capture, damit DOM-Textfelder (Spielername, Suche) weiter tippen koennen. */
export function needsBrowserCapture(code: number): boolean {
  return BROWSER_CAPTURE_KEY_CODES.has(code);
}

export function isControlBindingAllowed(binding: ControlBinding): boolean {
  if (binding.device === 'mouse') return MOUSE_BUTTONS.has(binding.button);
  return Number.isInteger(binding.code) && binding.code > 0 && binding.code < 256 && !isReservedKeyCode(binding.code);
}

function sanitizeKeyLabel(raw: unknown): string | undefined {
  if (typeof raw !== 'string') return undefined;
  const label = raw.trim();
  if (label.length === 0 || label.length > MAX_KEY_LABEL_LENGTH) return undefined;
  // Steuerzeichen und reine Leerzeichen sind keine anzeigbare Beschriftung.
  if (/[\u0000-\u001f\u007f]/.test(label)) return undefined;
  return label.toLocaleUpperCase();
}

/** Liest genau eine Belegung; `null` fuer alles, was nicht eindeutig gueltig ist. */
export function sanitizeControlBinding(raw: unknown): ControlBinding | null {
  if (typeof raw !== 'object' || raw === null) return null;
  const record = raw as Record<string, unknown>;
  if (record.device === 'key' && typeof record.code === 'number') {
    const label = sanitizeKeyLabel(record.label);
    const binding: ControlBinding = label ? { device: 'key', code: record.code, label } : { device: 'key', code: record.code };
    return isControlBindingAllowed(binding) ? binding : null;
  }
  if (record.device === 'mouse' && typeof record.button === 'number') {
    const binding = { device: 'mouse', button: record.button } as ControlBinding;
    return isControlBindingAllowed(binding) ? binding : null;
  }
  return null;
}

export function isSameControlBinding(a: ControlBinding | null | undefined, b: ControlBinding | null | undefined): boolean {
  if (!a || !b) return false;
  if (a.device === 'key' && b.device === 'key') return a.code === b.code;
  if (a.device === 'mouse' && b.device === 'mouse') return a.button === b.button;
  return false;
}

/** Entfernt Eintraege, die dem Standard entsprechen; das Dokument enthaelt nur echte Abweichungen. */
function normalizeOverrides(overrides: ControlBindingOverrides): ControlBindingOverrides {
  const result: ControlBindingOverrides = {};
  for (const action of CONTROL_ACTIONS) {
    if (!Object.prototype.hasOwnProperty.call(overrides, action.id)) continue;
    const binding = overrides[action.id] ?? null;
    if (binding && isSameControlBinding(binding, action.defaultBinding)
      && (binding.device !== 'key' || binding.label === undefined)) continue;
    result[action.id] = binding;
  }
  return result;
}

/**
 * Bereinigt je Eintrag: Unbekannte Aktionen und ungueltige oder reservierte Eingaben entfallen,
 * alle uebrigen Abweichungen bleiben erhalten. Ein kaputter Eintrag kostet nie die ganze Belegung.
 */
export function sanitizeControlBindingOverrides(raw: unknown): ControlBindingOverrides {
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) return {};
  const record = raw as Record<string, unknown>;
  const result: ControlBindingOverrides = {};
  for (const action of CONTROL_ACTIONS) {
    if (!Object.prototype.hasOwnProperty.call(record, action.id)) continue;
    const value = record[action.id];
    if (value === null) {
      result[action.id] = null;
      continue;
    }
    const binding = sanitizeControlBinding(value);
    if (binding) result[action.id] = binding;
  }
  return normalizeOverrides(result);
}

/**
 * Legt die Abweichungen ueber die Standards. Eine Eingabe gehoert hoechstens einer Aktion:
 * Eine ausdrueckliche Spielerwahl schlaegt einen Standard, der dann unbelegt bleibt. Unter
 * mehreren ausdruecklichen Wahlen (nur bei beschaedigtem Speicher) gewinnt die Aktionsreihenfolge.
 */
export function resolveControlBindings(overrides: ControlBindingOverrides): ResolvedControlBindings {
  const result = {} as Record<ControlActionId, ControlBinding | null>;
  const taken: ControlBinding[] = [];
  const isTaken = (binding: ControlBinding) => taken.some((entry) => isSameControlBinding(entry, binding));

  for (const action of CONTROL_ACTIONS) {
    if (!Object.prototype.hasOwnProperty.call(overrides, action.id)) continue;
    const binding = overrides[action.id] ?? null;
    if (binding && !isTaken(binding)) {
      result[action.id] = binding;
      taken.push(binding);
    } else {
      result[action.id] = null;
    }
  }
  for (const action of CONTROL_ACTIONS) {
    if (Object.prototype.hasOwnProperty.call(overrides, action.id)) continue;
    const binding = action.defaultBinding;
    if (isTaken(binding)) {
      result[action.id] = null;
    } else {
      result[action.id] = binding;
      taken.push(binding);
    }
  }
  return result;
}

export function findControlActionForBinding(
  resolved: ResolvedControlBindings,
  binding: ControlBinding,
): ControlActionId | null {
  for (const action of CONTROL_ACTIONS) {
    if (isSameControlBinding(resolved[action.id], binding)) return action.id;
  }
  return null;
}

export interface ControlBindingAssignment {
  readonly overrides: ControlBindingOverrides;
  /** Aktion, die bisher auf der neuen Eingabe lag und die alte Eingabe uebernommen hat. */
  readonly swappedWith: ControlActionId | null;
}

/**
 * Weist einer Aktion eine Eingabe zu. Ist sie bereits vergeben, uebernimmt die andere Aktion
 * die bisherige Eingabe (Tausch); so bleibt nach einer Spieleraenderung jede Aktion belegt.
 */
export function assignControlBinding(
  overrides: ControlBindingOverrides,
  action: ControlActionId,
  binding: ControlBinding,
): ControlBindingAssignment {
  if (!isControlBindingAllowed(binding)) throw new Error(`Control binding not allowed for ${action}`);
  const resolved = resolveControlBindings(overrides);
  const previous = resolved[action];
  const other = findControlActionForBinding(resolved, binding);
  const next: ControlBindingOverrides = { ...overrides, [action]: binding };
  const swappedWith = other && other !== action ? other : null;
  if (swappedWith) next[swappedWith] = previous;
  return { overrides: normalizeOverrides(next), swappedWith };
}
