/**
 * Dodge-window contract of every authored enemy danger zone: a player standing in the centre of a
 * zone must be able to react and run out of it before it hits.
 */
export const ENEMY_ZONE_FAIRNESS = { reactionMs: 250, playerSpeedPxPerSec: 280, playerRadiusPx: 16 } as const;

/** Shortest warning (ms) that lets a player in the centre of a zone of `radiusPx` step out of it. */
export function minimumZoneWarningMs(radiusPx: number): number {
  const { reactionMs, playerSpeedPxPerSec, playerRadiusPx } = ENEMY_ZONE_FAIRNESS;
  return reactionMs + (radiusPx + playerRadiusPx) / playerSpeedPxPerSec * 1000;
}
