// Directly from the catalog: i18n resolves `{key_<action>}` through these labels as well.
import { translate } from '../i18n/catalog';
import type { Locale } from '../i18n/types';
import { KEY_CODES, type ControlBinding } from './controlBindings';

/** Benannte Tasten: Anzeige ueber `ui.keys.<name>` in der jeweiligen Sprache. */
const NAMED_KEYS: Readonly<Record<number, string>> = {
  [KEY_CODES.BACKSPACE]: 'backspace',
  [KEY_CODES.TAB]: 'tab',
  [KEY_CODES.ENTER]: 'enter',
  [KEY_CODES.SHIFT]: 'shift',
  [KEY_CODES.CTRL]: 'ctrl',
  [KEY_CODES.ALT]: 'alt',
  19: 'pause',
  20: 'capsLock',
  [KEY_CODES.ESC]: 'escape',
  [KEY_CODES.SPACE]: 'space',
  [KEY_CODES.PAGE_UP]: 'pageUp',
  [KEY_CODES.PAGE_DOWN]: 'pageDown',
  [KEY_CODES.END]: 'end',
  [KEY_CODES.HOME]: 'home',
  [KEY_CODES.LEFT]: 'left',
  [KEY_CODES.UP]: 'up',
  [KEY_CODES.RIGHT]: 'right',
  [KEY_CODES.DOWN]: 'down',
  [KEY_CODES.PRINT_SCREEN]: 'printScreen',
  45: 'insert',
  46: 'delete',
  [KEY_CODES.META_LEFT]: 'meta',
  [KEY_CODES.META_RIGHT]: 'meta',
  [KEY_CODES.CONTEXT_MENU]: 'contextMenu',
  144: 'numLock',
  145: 'scrollLock',
};

/** Ziffernblock: „Num 5“, „Num +“. */
const NUMPAD_KEYS: Readonly<Record<number, string>> = {
  96: '0', 97: '1', 98: '2', 99: '3', 100: '4', 101: '5', 102: '6', 103: '7', 104: '8', 105: '9',
  106: '*', 107: '+', 109: '-', 110: ',', 111: '/',
};

/**
 * Satzzeichen-Tasten haengen vom Tastaturlayout ab (Ö, Ü, #, ß ...). Die Erfassung speichert
 * deshalb das tatsaechlich gedrueckte Zeichen; diese US-Zeichen sind nur der Rueckfall.
 */
const OEM_FALLBACK: Readonly<Record<number, string>> = {
  59: ';', 61: '=', 173: '-', 186: ';', 187: '=', 188: ',', 189: '-', 190: '.', 191: '/', 192: '`',
  219: '[', 220: '\\', 221: ']', 222: "'", 226: '<',
};

const MOUSE_KEYS: Readonly<Record<number, string>> = { 1: 'mouseMiddle', 3: 'mouse4', 4: 'mouse5' };

/**
 * Nur layoutabhaengige Satzzeichen-Tasten brauchen das bei der Erfassung gedrueckte Zeichen;
 * alle anderen Tasten lassen sich aus dem keyCode selbst beschriften.
 */
export function needsCapturedKeyLabel(code: number): boolean {
  return NAMED_KEYS[code] === undefined && NUMPAD_KEYS[code] === undefined
    && !(code >= 65 && code <= 90) && !(code >= 48 && code <= 57)
    && !(code >= KEY_CODES.F1 && code <= KEY_CODES.F1 + 23);
}

export function formatKeyCodeLabel(code: number, locale: Locale, capturedLabel?: string): string {
  const named = NAMED_KEYS[code];
  if (named) return translate(locale, `ui.keys.${named}`);
  if (code >= 65 && code <= 90) return String.fromCharCode(code);
  if (code >= 48 && code <= 57) return String.fromCharCode(code);
  if (code >= KEY_CODES.F1 && code <= KEY_CODES.F1 + 23) return `F${code - KEY_CODES.F1 + 1}`;
  const numpad = NUMPAD_KEYS[code];
  if (numpad) return translate(locale, 'ui.keys.numpad', { key: numpad });
  if (capturedLabel) return capturedLabel;
  const oem = OEM_FALLBACK[code];
  if (oem) return oem;
  return translate(locale, 'ui.keys.code', { code });
}

/** Anzeige einer Belegung in Fliesstext und auf Tastenkappen; `null` = nicht belegt. */
export function formatControlBindingLabel(binding: ControlBinding | null, locale: Locale): string {
  if (!binding) return translate(locale, 'ui.keys.unbound');
  if (binding.device === 'mouse') return translate(locale, `ui.keys.${MOUSE_KEYS[binding.button]}`);
  return formatKeyCodeLabel(binding.code, locale, binding.label);
}
