/**
 * Steuerungsübersicht der Tutorial-Tafel auf der Einstiegs-Map (`ui/CoopDefenseTutorialPanel`,
 * über `ui/CenterHUD`). Außerhalb des Tutorials erklärt der Dialog „Tastenbelegung“ die Tasten.
 *
 * Hier stehen ausschließlich Spieler-Steuerungen. Entwickler-Werkzeuge (Debug-Overlays,
 * Diagnose-Tasten) gehören bewusst nicht in diese Liste, weil sie sonst im Tutorial
 * sichtbar wären. Die Zeilenzahl bestimmt die Höhe der Tutorial-Tafel und damit die
 * Felsformation unter ihr auf der Einstiegs-Map.
 *
 * Tasten stehen nie wörtlich hier: Belegbare Aktionen zeigen die aktuelle Spielerbelegung,
 * nur feste Eingaben (Waffen auf den Maustasten, Esc) haben eine eigene Beschriftung. Die
 * Kappenbeschriftung erzeugt `controls/helpControlLabels`; diese Datei bleibt reine Daten, weil
 * die Arena-Generierung sie über `coopDefenseTutorial` schon beim Laden der Konfiguration liest.
 */
import type { ControlActionId } from '../controls/controlBindings';

export type HelpControlInput =
  /** Mehrere Aktionen in einer Kappe, etwa die vier Bewegungsrichtungen. */
  | { readonly kind: 'actions'; readonly actions: readonly ControlActionId[] }
  | { readonly kind: 'action'; readonly action: ControlActionId; readonly hold?: boolean }
  | { readonly kind: 'fixed'; readonly labelKey: string };

export interface HelpControlEntry {
  readonly input: HelpControlInput;
  readonly descriptionKey: string;
}

export const HELP_CONTROLS: readonly HelpControlEntry[] = [
  { input: { kind: 'actions', actions: ['moveUp', 'moveLeft', 'moveDown', 'moveRight'] }, descriptionKey: 'ui.help.move' },
  { input: { kind: 'action', action: 'dash' }, descriptionKey: 'ui.help.dash' },
  { input: { kind: 'fixed', labelKey: 'ui.help.leftMouse' }, descriptionKey: 'ui.help.weapon1' },
  { input: { kind: 'fixed', labelKey: 'ui.help.rightMouse' }, descriptionKey: 'ui.help.weapon2' },
  { input: { kind: 'action', action: 'utility', hold: true }, descriptionKey: 'ui.help.utility' },
  { input: { kind: 'action', action: 'utilityWheel', hold: true }, descriptionKey: 'ui.help.utilityWheel' },
  { input: { kind: 'action', action: 'ultimate' }, descriptionKey: 'ui.help.ultimate' },
  { input: { kind: 'action', action: 'interact' }, descriptionKey: 'ui.help.burrow' },
  { input: { kind: 'fixed', labelKey: 'ui.keys.escape' }, descriptionKey: 'ui.help.options' },
];
